## 7️⃣ Using PMTiles in a React component (common pattern)

```tsx
// src/Map.tsx
import React, { useEffect, useRef } from 'react';
import maplibregl from 'maplibre-gl';
import * as pmtiles from 'pmtiles';
import 'maplibre-gl/dist/maplibre-gl.css';

const pmtilesProtocol = new pmtiles.Protocol();
maplibregl.addProtocol('pmtiles', pmtilesProtocol.tile);

export const Map = () => {
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!containerRef.current) return;

    const map = new maplibregl.Map({
      container: containerRef.current,
      style: {
        version: 8,
        sources: {
          world: {
            type: 'vector',
            url: 'pmtiles://https://my-cdn.example.com/tiles/world.pmtiles'
          }
        },
        layers: [
          {
            id: 'water',
            type: 'fill',
            source: 'world',
            'source-layer': 'water',
            paint: { 'fill-color': '#a0c8f0' }
          }
        ]
      },
      center: [0, 0],
      zoom: 2
    });

    return () => {
      map.remove();               // clean up the map
      // optional: remove the protocol when the last map is destroyed
      // maplibregl.removeProtocol('pmtiles');
    };
  }, []);

  return <div ref={containerRef} style={{ width: '100%', height: '100%' }} />;
};
```

*Only the `addProtocol` call lives outside the component (module‑level) so it runs once even if the component mounts/unmounts many times.*

