## 6️⃣ Minimal Reproducible Example (v4)

```html
<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8" />
  <title>MapLibre v4 + custom protocol</title>
  <link href="https://unpkg.com/maplibre-gl@4.4.0/dist/maplibre-gl.css" rel="stylesheet" />
  <style>#map { position:absolute; top:0; bottom:0; width:100%; }</style>
</head>
<body>
<div id="map"></div>

<script type="module">
  import maplibregl from 'https://unpkg.com/maplibre-gl@4.4.0/dist/maplibre-gl.js';
  import * as pmtiles from 'https://cdn.jsdelivr.net/npm/pmtiles@3.0.0/dist/index.min.js';

  // ---- 1️⃣ Register PMTiles protocol (v4‑compatible) ----
  const pm = new pmtiles.Protocol();
  maplibregl.addProtocol('pmtiles', pm.tile);

  // ---- 2️⃣ Create the map ----
  const map = new maplibregl.Map({
    container: 'map',
    style: {
      version: 8,
      sources: {
        world: {
          type: 'vector',
          // NOTE: use `url:` (not `tiles:`) so the protocol can read the header.
          url: 'pmtiles://https://static.example.com/world.pmtiles'
        }
      },
      layers: [
        {
          id: 'water',
          type: 'fill',
          source: 'world',
          'source-layer': 'water',
          paint: { 'fill-color': '#a0c8f0' }
        },
        {
          id: 'roads',
          type: 'line',
          source: 'world',
          'source-layer': 'road',
          paint: { 'line
